<template>
 <b-modal id="patternModal" :title="creating?'New pattern':'Edit pattern'" size="xl" scrollable hide-footer @show="open">
  <b-alert :show="!!error" variant="danger" role="alert">{{ error }}</b-alert>
  <p class="pattern-intro">Define a rule on the left and test it against a traffic fragment.</p>
  <b-form @submit.prevent="save">
   <div v-if="creating" class="pattern-presets"><span>Start from an example</span><b-button type="button" size="sm" variant="outline-secondary" @click="preset('flag')">CTF flag</b-button><b-button type="button" size="sm" variant="outline-secondary" @click="preset('text')">Text</b-button><b-button type="button" size="sm" variant="outline-secondary" @click="preset('bytes')">HEX bytes</b-button></div>
   <div class="pattern-editor-grid">
    <section class="pattern-editor-section"><div class="pattern-section-heading"><span class="pattern-step">01</span><h6>Search conditions</h6></div>
     <div class="row"><b-form-group class="col-md-8" label="Name" label-for="pattern-name"><b-form-input id="pattern-name" v-model="form.name" required maxlength="256" placeholder="E.g. flag in response" autofocus/></b-form-group><b-form-group class="col-md-4" label="Group" label-for="pattern-group"><b-form-input id="pattern-group" v-model="form.group" maxlength="64" list="pattern-groups" placeholder="Flags, noise…"/><datalist id="pattern-groups"><option v-for="g in groups" :key="g">{{ g }}</option></datalist></b-form-group></div>
     <b-form-group label="Match type"><b-form-radio-group v-model="form.searchType" buttons button-variant="outline-primary" class="pattern-methods" :options="[{value:'SUBSTRING',text:'Exact text'},{value:'REGEX',text:'Regex'},{value:'SUBBYTES',text:'HEX bytes'}]"/></b-form-group>
     <b-form-group label="Search value" label-for="pattern-value" :description="methodHelp"><b-form-textarea id="pattern-value" v-model="form.value" required rows="3" maxlength="4096" :placeholder="placeholder" class="pattern-code" spellcheck="false"/></b-form-group>
     <div class="row"><b-form-group class="col-md-6" label="Search in" label-for="pattern-direction"><b-form-select id="pattern-direction" v-model="form.directionType" :options="[{value:'BOTH',text:'Requests and responses'},{value:'INPUT',text:'Requests only'},{value:'OUTPUT',text:'Responses only'}]"/></b-form-group><b-form-group class="col-md-6" label="Service" label-for="pattern-service"><b-form-select id="pattern-service" v-model="form.serviceId" :options="services"/></b-form-group></div>
     <b-form-group label="Action on match" label-for="pattern-action"><b-form-select id="pattern-action" v-model="form.actionType" :options="[{value:'FIND',text:'Label session and highlight match'},{value:'IGNORE',text:'Hide the entire matching session'}]"/></b-form-group>
     <b-alert :show="form.actionType==='IGNORE'" variant="warning">A match hides the entire session. Test the rule before enabling it.</b-alert>
     <div class="pattern-color"><span class="small">Label color</span><div class="pattern-swatches"><button v-for="color in palette" :key="color" type="button" class="swatch" :style="{backgroundColor:color}" :aria-label="'Color '+color" :aria-pressed="String(form.color===color)" @click="form.color=color" :class="{chosen:form.color===color}"/><input type="color" v-model="form.color" aria-label="Custom color"/></div><b-form-checkbox v-model="form.enabled" switch>Enabled</b-form-checkbox></div>
    </section>
    <section class="pattern-test"><div class="pattern-section-heading"><span class="pattern-step">02</span><h6>Test with an example</h6></div><p class="small text-muted">Check the rule before saving. This test does not change saved traffic.</p>
     <div class="pattern-test-controls"><label for="pattern-sample">Traffic fragment</label><b-form-checkbox v-model="sampleHex">HEX example</b-form-checkbox></div>
     <b-form-textarea id="pattern-sample" v-model="sample" rows="6" maxlength="16384" placeholder="Paste a request or response fragment" aria-label="Test fragment" class="pattern-code" spellcheck="false"/>
     <div class="pattern-test-actions"><b-form-select v-model="incoming" aria-label="Test fragment direction" :options="[{value:false,text:'Response'},{value:true,text:'Request'}]"/><b-button type="button" variant="outline-primary" :disabled="testing" @click="test">{{ testing?'Testing…':'Test' }}</b-button></div>
     <div v-if="result" class="pattern-result" role="status"><strong :class="result.ignored?'text-warning':result.matches.length?'text-success':'text-muted'">{{ result.ignored?'Session will be hidden':result.matches.length ? 'Matches: '+result.matches.length : 'No matches' }}</strong><pre v-if="!sampleHex&&form.searchType!=='SUBBYTES'" class="sample-preview"><template v-for="(part,i) in preview"><mark v-if="part.hit" :key="i">{{part.text}}</mark><span v-else :key="i">{{part.text}}</span></template></pre><small v-else-if="result.matches.length" class="d-block">Positions: {{ result.matches.map(m=>`${m.startPosition}–${m.endPosition}`).join(', ') }}</small></div>
     <div v-else class="pattern-test-empty"><span class="pattern-empty-line"/><p>Matches will appear here.<br>Paste an example and click Test.</p></div>
    </section>
   </div>
   <div class="pattern-editor-footer"><p>The rule applies to new traffic. Use Search history in the pattern manager to check saved traffic.</p><div><b-button type="button" variant="outline-secondary" @click="$bvModal.hide('patternModal')">Cancel</b-button><b-button type="submit" variant="primary" :disabled="saving">{{ saving?'Saving…':creating?'Create pattern':'Save' }}</b-button></div></div>
  </b-form>
 </b-modal>
</template>
<script>
const defaults=()=>({name:'',group:'',value:'',searchType:'SUBSTRING',directionType:'BOTH',actionType:'FIND',serviceId:null,color:'#ff7474',enabled:true});
const message=e=>e.response?.data?.error||e.message;
export default {
 props:{creating:Boolean,initialPattern:Object},
 data:()=>({form:defaults(),error:'',sample:'',sampleHex:false,incoming:false,result:null,testing:false,saving:false,generation:0,palette:['#ff7474','#ffd166','#65c9a5','#64b5f6','#b39ddb','#f48fb1']}),
 computed:{groups(){return [...new Set(this.$store.state.patterns.filter(p=>!p.deleted&&p.group).map(p=>p.group))]},services(){return [{value:null,text:'All services'},...this.$store.state.services.map(s=>({value:s.port,text:`${s.name} · ${s.port}`}))]},placeholder(){return {REGEX:'[A-Z0-9]{31}=',SUBSTRING:'FLAG_',SUBBYTES:'46 4c 41 47 5f'}[this.form.searchType]},methodHelp(){return {REGEX:'Go / RE2 syntax. No lookbehind or backreferences; stream search window: 64 KiB.',SUBSTRING:'Case-sensitive exact text search.',SUBBYTES:'Hexadecimal digit pairs. Spaces and line breaks are allowed.'}[this.form.searchType]},preview(){let start=0;const out=[];for(const m of this.result?.matches||[]){const a=m.startPosition,b=m.endPosition+1;if(a<start||b>this.sample.length)continue;out.push({text:this.sample.slice(start,a),hit:false},{text:this.sample.slice(a,b),hit:true});start=b}out.push({text:this.sample.slice(start),hit:false});return out}},
 watch:{form:{deep:true,handler(){this.result=null;this.generation++}},sample(){this.result=null;this.generation++},sampleHex(){this.result=null;this.generation++},incoming(){this.result=null;this.generation++}},
 methods:{
  open(){this.form={...defaults(),...this.initialPattern};this.error='';this.result=null;this.sample='';this.sampleHex=false;this.incoming=this.form.directionType==='INPUT'},
  body(){return {...this.form,value:this.form.searchType==='SUBBYTES'?this.form.value.replace(/\s+/g,'').toLowerCase():this.form.value}},
  preset(kind){if(kind==='flag'){Object.assign(this.form,{name:'CTF flag',group:'Flags',searchType:'REGEX',value:'[A-Z0-9]{31}=',directionType:'OUTPUT'});this.sample='Response: ABCDEFGHIJKLMNOPQRSTUVWXYZ01234=';}else if(kind==='text'){Object.assign(this.form,{searchType:'SUBSTRING',value:'FLAG_'});}else{Object.assign(this.form,{searchType:'SUBBYTES',value:'46 4c 41 47 5f'});this.sample='FLAG_example'}},
  async test(){this.testing=true;this.error='';const generation=this.generation;try{const {data}=await this.$http.post('/v2/pattern-test',{pattern:{...this.body(),name:this.form.name||'Preview'},text:this.sample,hex:this.sampleHex,incoming:this.incoming});if(generation===this.generation)this.result=data;}catch(e){this.error=message(e)}finally{this.testing=false}},
  async save(){this.saving=true;this.error='';try{const body=this.body();const {data}=this.creating?await this.$http.post('/pattern/',body):await this.$http.put(`/pattern/${body.id}`,body);this.$store.commit('setPatterns',(await this.$http.get('/pattern/')).data);this.$emit('patternAddComplete',data);this.$bvModal.hide('patternModal')}catch(e){this.error=message(e)}finally{this.saving=false}},
 }
}
</script>
<style scoped>
.pattern-intro{color:var(--gm-muted);font-size:12px;margin-bottom:8px}.pattern-presets{display:flex;flex-wrap:wrap;align-items:center;gap:6px;padding:0 0 10px}.pattern-presets>span{font-size:12px;color:var(--gm-muted);margin-right:4px}.pattern-editor-grid{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,1fr);gap:10px}.pattern-editor-section,.pattern-test{padding:12px;border:1px solid var(--gm-border);border-radius:8px;min-width:0}.pattern-test{background:var(--gm-panel-alt);align-self:start}.pattern-section-heading{display:flex;align-items:center;gap:8px;margin-bottom:10px}.pattern-section-heading h6{margin:0;font-size:13px;font-weight:700}.pattern-step{font-family:var(--gm-mono);font-size:12px;color:var(--gm-accent);background:var(--gm-accent-soft);padding:2px 5px;border-radius:4px}.pattern-code,.sample-preview{font-family:var(--gm-mono)}.pattern-methods{display:flex;flex-wrap:wrap}.pattern-color{display:flex;flex-wrap:wrap;align-items:center;gap:8px}.pattern-swatches{display:flex;flex-wrap:wrap;gap:8px;align-items:center}.swatch{width:26px;height:26px;border:2px solid transparent;border-radius:50%}.swatch.chosen{outline:2px solid var(--gm-text);outline-offset:2px}.pattern-swatches input{width:30px;height:30px;padding:0;border:0;background:transparent}.pattern-test-controls{display:flex;flex-wrap:wrap;justify-content:space-between;gap:6px;align-items:center;font-size:12px;margin-bottom:6px}.pattern-test-controls label{margin:0}.pattern-test-actions{display:flex;gap:6px;margin-top:8px}.pattern-test-actions select{flex:1;min-width:0}.pattern-result{padding-top:10px;margin-top:10px;border-top:1px solid var(--gm-border)}.sample-preview{white-space:pre-wrap;overflow-wrap:anywhere;max-height:220px;overflow:auto;margin-top:8px;margin-bottom:0;padding:8px;background:var(--gm-panel);color:var(--gm-text);border-radius:6px}.pattern-test-empty{text-align:center;padding:16px 0 0;font-size:12px;color:var(--gm-muted)}.pattern-empty-line{display:block;width:28px;height:2px;background:var(--gm-border);margin:0 auto 8px;border-radius:2px}.pattern-editor-footer{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:10px;border-top:1px solid var(--gm-border);margin-top:12px;padding-top:10px}.pattern-editor-footer p{font-size:12px;color:var(--gm-muted);max-width:52ch;margin:0}.pattern-editor-footer>div{display:flex;gap:6px}
@media(max-width:767px){.pattern-editor-grid{grid-template-columns:1fr}.pattern-editor-section,.pattern-test{padding:10px}.pattern-editor-footer>div{width:100%}.pattern-editor-footer .btn{flex:1}}
</style>
